def countServers(grid):
    m, n = len(grid), len(grid[0])
    row_count = [0] * m
    col_count = [0] * n

    # Count servers in each row and column
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                row_count[i] += 1
                col_count[j] += 1

    total = 0
    # Count servers that can communicate
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                if row_count[i] > 1 or col_count[j] > 1:
                    total += 1
    return total
